private function roundHalfUp(string $value, int $precision): string
{
    // assume positive
    $factor = bcpow('10', (string)$precision, 0);
    $shifted = bcmul($value, $factor, $precision + 2);
    // add 0.5
    $shifted = bcadd($shifted, '0.5', 0);
    // floor via int cast? bcadd returns string. We can truncate decimal.
    // Since we have integer string, just divide
    $roundedInt = $shifted; // bcadd with scale 0 gives integer
    $result = bcdiv($roundedInt, $factor, $precision);
    // ensure exactly precision digits
    return number_format((float)$result, $precision, '.', '') ?: $result;
}

